<?php

declare(strict_types=1);

use Rylacdang\Formcast\Emitters\EnumEmitter;

enum SampleStringEnum: string
{
    case Cash = 'cash';
    case Gcash = 'gcash';
    case Card = 'card';
}

enum SampleIntEnum: int
{
    case Low = 1;
    case Medium = 2;
    case High = 3;
}

it('emits string-backed php enums as typescript const objects and union types', function (): void {
    $emitter = new EnumEmitter;

    $output = $emitter->emit(SampleStringEnum::class);

    expect($output)->toBe(<<<'TS'
// Generated by Formcast. Do not edit.
// Source: SampleStringEnum

export const SampleStringEnum = {
  Cash: 'cash',
  Gcash: 'gcash',
  Card: 'card',
} as const;

export type SampleStringEnum = (typeof SampleStringEnum)[keyof typeof SampleStringEnum];

TS);
});

it('emits int-backed php enums with numeric values', function (): void {
    $emitter = new EnumEmitter;

    $output = $emitter->emit(SampleIntEnum::class);

    expect($output)->toContain("  Low: 1,\n  Medium: 2,\n  High: 3,");
});
